python3 -c "
s = '.....((((.(((((....))))).(((....))).)).))....((((.(((....))).(((....))).))))....................'
print(f'Length: {len(s)}')
# Parse pairs
stack = []
pairs = []
for i, c in enumerate(s):
    if c == '(':
        stack.append(i)
    elif c == ')':
        if stack:
            j = stack.pop()
            pairs.append((j, i))
        else:
            print(f'ERROR: unmatched ) at {i}')
if stack:
    print(f'ERROR: unmatched ( at {stack}')

pairs.sort()
print('Pairs:')
for i, j in pairs:
    print(f'  ({i},{j})')

# Compute stems
stems = []
cur_stem = []
for i, j in pairs:
    if not cur_stem:
        cur_stem = [(i, j)]
    else:
        pi, pj = cur_stem[-1]
        if i == pi + 1 and j == pj - 1:
            cur_stem.append((i, j))
        else:
            stems.append(cur_stem)
            cur_stem = [(i, j)]
if cur_stem:
    stems.append(cur_stem)

print('\\nStems:')
for idx, stem in enumerate(stems):
    lo = stem[-1]
    hi = stem[0]
    print(f'  Stem {idx}: ({lo[0]},{lo[1]}) to ({hi[0]},{hi[1]}), len={len(stem)}')

# Hairpin loops
for stem in stems:
    lo = stem[-1]
    loop_start = lo[0] + 1
    loop_end = lo[1]
    loop = s[loop_start:loop_end]
    if loop:
        if not any(c in '()' for c in loop):
            print(f'  Hairpin after stem ending at {lo}: loop positions {loop_start}-{loop_end-1}, seq={loop}')
"

